/// Alternate tellings, batch J: the same cases, played out another way.
extension StoryVariants {
    static let variantsJ: [CaseTemplate] = [coachRecruitBribesV1, neverHeldFestivalV1, falseTeamAccusationV1, deviceOnDeliveryDriverV1, lotteryClerkInsiderV1, mugshotRemovalFeesV1, laneClosurePaybackV1, neighborsWatchStabbingV1, unneededSurgeriesV1, phantomPatientClaimsV1, tornadoReliefKeptV1, slowCarHoodClaimsV1, localCelebrityTrackerV1, syrupReserveHeistV1, reptileHoardCrueltyV1, brotherNameForTwentyYearsV1, droneDropAtTheYardV1, riggedMidwayGameV1, santaSuitIntruderV1, fortyDollarBankNoteV1, stormLootingCrewV1, vacationRentalNoHouseV1, fairgroundSwingFallV1, campgroundBluegrassBrawlV1, horseShowTreasurerV1]

    static let coachRecruitBribesV1 = SmallCases.make(
        key: "story.coachRecruitBribes",
        category: .whiteCollar,
        headlines: ["University Rowing Coach Sold Scholarship Spots in Cash-Stuffed Envelopes", "Boat House Roster Has Names No One Has Ever Seen"],
        law: "bribery",
        threshold: 8,
        spec: "Corruptly accepted a thing of value as a public official, on or about {DATE}.",
        ages: 28...60,
        victim: false,
        summary: "{D}, a state university rowing coach, accepted $75,000 in envelopes from three families around {DATE} and put their teenagers on the recruit list, though none ever sat in a boat. A compliance clerk noticed empty practice sheets. {DL} says the envelopes were gifts to the boat club.",
        state: [E(.document, 3, "Practice Sheets", "Three listed recruits never signed in once."), E(.digital, 3, "Bank Deposits", "Cash deposits after each roster change."), E(.statement, 2, "Parent Interview", "A parent says a price was named for a spot.")],
        defense: [E(.document, 1, "Boat Club Ledger", "A ledger showing gifts logged to the club.")],
        role: "Compliance officer",
        exam: [.direct("What does a compliance officer do at the university?", "\"I audit athletic recruiting. I make sure every athlete on a recruit list is real, enrolled, and actually participating in the sport.\""), .direct("How did this case reach your desk?", "\"A clerk noticed practice sheets for the rowing program that had three names on the recruit list and not one signature in a boat.\""), .direct("What did the practice sheets show?", "\"Three listed recruits never signed in once. Not a single practice, not a single erg session, across a whole season.\""), .direct("What did the bank deposits show?", "\"Cash deposits made after each roster change. The timing lined up with the roster edits, which is why I paid attention.\""), .direct("What did a parent tell you?", "\"One parent said a price was named for a spot on the team. That interview is in evidence and it was consistent with the others.\""), .direct("What total was involved?", "\"About $75,000 in envelopes from three families, around {DATE}. That is what moved from families to the coach.\""), .direct("What did {D} say when you asked about the envelopes of cash?", "\"{D} said they were gifts to the boat club and not payments for roster spots. But three families were on the recruit list, and none of the teenagers ever practiced.\""), .cross("Is it unusual for a recruit to be listed and never show up?", "\"It happens, rarely. Injuries and changes of mind occur. But three in a row, each followed by a deposit, is a pattern.\""), .cross("Did you see {DL} take an envelope?", "\"No. I did not witness a handoff. I reviewed documents and interviewed people.\""), .cross("Did the boat club accept gifts legally?", "\"Yes, the club can accept gifts. That is not in dispute. The question is whether those gifts bought roster spots.\""), .cross("Did {DL} deny putting the teenagers on the list?", "\"No. {D.He} agreed the names were on the list. {D.He} disputed what the money was for.\""), .cross("Did {DL} cooperate with the audit?", "\"Yes. {D.He} handed over records and answered questions without delay.\"")],
        defenseRole: "Boat club volunteer",
        defenseExam: [.direct("What is your role at the boat club?", "\"I volunteer, helping with fundraising and keeping the ledger for gifts.\""), .direct("How does the club receive gifts?", "\"People hand them to coaches or to me. We log each one in the ledger and use them for equipment.\""), .direct("Did {DL} give you envelopes?", "\"Yes, a few times. {D} handed envelopes to the club for the oar fund and I logged them.\""), .direct("What did the club buy with gifts?", "\"Oars, oarlocks, and a trailer repair. I can show purchases from the ledger.\""), .direct("Did families say they wanted a spot?", "\"I did not hear that. They said they wanted to support the team.\""), .direct("Does the ledger show these gifts?", "\"Yes, entries match some of the envelopes.\""), .direct("How did you log the gifts from the families in the boat club ledger?", "\"I wrote each gift in the club ledger with the date and amount, and I kept the notes in a folder. Some of the gifts paid for real oars and repairs.\""), .direct("What did you see {D} do with the envelopes that were handed over?", "\"{DF} handed envelopes to me, and I logged them. I did not see inside every one, and I did not ask who gave them or why.\""), .direct("Did the three teenagers ever row with the boat club?", "\"Not that I recall. I never saw them at the dock, and I cannot say why they were on the university's recruit list.\""), .cross("Does the ledger show all $75,000?", "\"I would have to check the totals. I do not think every dollar is logged.\""), .cross("Did you count the cash?", "\"Sometimes. Not always. {D.He} often handed it over in sealed envelopes.\""), .cross("Did any listed recruit ever practice?", "\"Not that I saw. I never saw them at the dock.\""), .cross("Did {DL} say the gifts were tied to recruiting?", "\"No. Never to me.\""), .cross("Who deposited the money?", "\"Sometimes {DF}. I do not know every deposit.\"")],
        theory: ("{D} traded roster places for cash.", "Gifts to a club."),
        allocution: "\"I knew better than to take it.\"",
        truths: ("{DL} paid off a boat loan with the deposits.", "The club ledger shows real oar purchases from some gifts."),
        defendant: [.direct("What is your role at the university?", "\"I coach the rowing team. I recruit, train, and manage the roster for the whole season.\""), .direct("Where did the $75,000 go?", "\"Into the boat club. Families gave gifts to support the program, and I turned the envelopes over to the club.\""), .direct("Why were the three teenagers on the recruit list?", "\"I listed them as prospects. I hoped they would join. I did not guarantee them anything.\""), .direct("Did a family tell you what they wanted?", "\"Some mentioned wanting their child considered. I said I would look at them like any prospect.\""), .direct("Why did the deposits follow the roster changes?", "\"Families gave around the same time. It was a coincidence of timing, not a trade.\""), .direct("Did you intend to sell roster spots?", "\"No. I never sold anything. I accepted gifts for a club I loved and I should have kept them separate from recruiting.\""), .direct("What did you do with part of the cash deposits?", "\"I paid off a boat loan with some of the deposits. I considered it a club expense, but I know the jury may see a personal benefit there.\""), .cross("You put three teenagers on a recruit list who never rowed, didn't you?", "\"Yes. I did. They never joined, and I should not have listed them without more proof.\""), .cross("A parent says a price was named, doesn't the parent?", "\"Maybe a parent heard it that way. I never named a price.\""), .cross("You accepted $75,000 in envelopes, didn't you?", "\"Yes. I did, and I deposited them. I handled it poorly.\""), .cross("Cash deposits followed roster changes, didn't they?", "\"So it appears. I did not plan it that way.\""), .cross("You knew the university forbids this, didn't you?", "\"I knew gifts must be handled carefully. I should have involved the compliance office.\"")],
        openings: ("A rowing coach at a state university accepted $75,000 in envelopes from three families and put their teenagers on the recruit list, though none ever sat in a boat. The State will show empty practice sheets, cash deposits, and a parent who heard a price.", "A boat club ledger, a volunteer who logged the gifts, and oars that were actually bought. {D} says every envelope was a gift to the club, and a ledger will tell you what happened to it."),
        closings: ("Three teenagers on a recruit list, no practice, no boat, and cash deposited each time the roster changed. A parent heard a price named. Those spots were for sale.", "Gifts to a boat club, logged in a ledger and used for oars. The State has not proved {D} sold roster spots, only that recruiting and giving were handled poorly."),
        timeline: [(-120, "The first family meets {DL}."), (0, "The final envelope."), (45, "Compliance flags blank sheets."), (100, "Charges.")],
        identified: "Practice sheets and bank deposits.",
        aggravating: ["The defendant took advantage of a position of trust or confidence", "The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let neverHeldFestivalV1 = SmallCases.make(
        key: "story.neverHeldFestival",
        category: .whiteCollar,
        headlines: ["Mountain Music Retreat Sold Out in Days and Never Opened", "Ticket Holders Meet a Closed Gate and a Gravel Lot"],
        law: "falsePretenses100k",
        threshold: 8,
        spec: "Obtained over $100,000 by false pretenses from {V} and others, in the weeks before {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D}, an event organizer, sold 1,300 weekend passes worth $360,000 over the weeks before {DATE} for a mountain music retreat with named headliners and lodge stays. On {DATE}, opening day, the gate was chained and no band had been booked. {DL} says the venue backed out.",
        state: [E(.digital, 3, "Pass Sales Report", "$360,000 collected over two months."), E(.document, 3, "Headliner Lineup", "Artists listed who never signed contracts."), E(.document, 2, "Account Statements", "Most funds moved out within days.")],
        defense: [E(.document, 1, "Venue Emails", "Emails with a venue about dates.")],
        role: "Pass holder",
        exam: [.direct("What did you buy from {D}?", "\"A weekend pass to a mountain music retreat with named headliners and lodge stays. I paid for it weeks ahead, with 1,300 other pass holders.\""), .direct("What did you find on opening day?", "\"The gate was chained and no band had been booked. There was no staff, no stage, and nobody to tell us anything.\""), .direct("What did the lineup and the account statements show?", "\"Artists were listed who never signed contracts. The account statements show most of the funds moved out within days of being paid.\""), .direct("Tell the jury why you bought a pass.", "\"I love live music and I wanted a weekend in the mountains. The lineup had several artists I follow, and I planned to drive up with friends and book the lodge.\""), .direct("What did you do to prepare for the weekend?", "\"I paid for the pass and booked a night at the lodge. I took the time off work and drove several hours to get there on opening day.\""), .direct("What did you find when you arrived?", "\"The gate was chained and no one was there. No band was setting up, and a handwritten sign said the event was cancelled. I was stunned.\""), .cross("{D} says the venue backed out, doesn't {D.he}?", "\"Yes. A venue manager says that happened, and I will agree that is part of what I have been told.\""), .cross("Was any money ever refunded to pass holders?", "\"No. I was never refunded, and I have not heard of anyone who was.\""), .cross("Did {D} make any effort to hold the event?", "\"I do not know. I saw no sign of it on opening day, only a chain on a gate.\""), .cross("Did you ever hear from the defendant before opening day about any trouble with the venue?", "\"No. I got no message before I arrived. If I had been told about a problem, I would not have made the trip.\""), .cross("Did the defendant offer a refund afterward?", "\"Not to me. I asked for one by email and heard nothing back for weeks. I do not know how many others were refunded.\"")],
        defenseRole: "Venue manager",
        defenseExam: [.direct("Did {D} reach out to your venue about holding the retreat?", "\"Several times. {D} called and emailed about dates, prices, and what the lodge could host over a weekend.\""), .direct("Was a deposit paid to your venue for the retreat?", "\"A small one. It was a fraction of what the full booking would have required, and nothing more followed.\""), .direct("Tell us about your venue.", "\"I manage a mountain lodge and event grounds. We host weddings, retreats, and concerts, and we require a deposit and a signed contract for every booking.\""), .direct("What dealings did you have with the defendant?", "\"{D.He} called and emailed several times about dates and prices. {D.He} paid a small deposit, but never the balance that our contract required.\""), .direct("Why did your venue back out of the retreat?", "\"The balance was never paid. After weeks of reminders, we released the dates to another group, because we could not hold them without payment.\""), .direct("What did the defendant say about the retreat when the deposit was paid?", "\"That a large crowd was coming and the headliners were nearly confirmed. We agreed on dates, and {D.he} never paid the balance.\""), .cross("Did the defendant ever pay the balance owed on the booking?", "\"No. The balance was never paid. We waited until the dates were close and then we released them.\""), .cross("Did you know the defendant had already sold 1,300 passes?", "\"Not at the time. I only learned that afterward, from the news and from angry pass holders calling the lodge.\""), .cross("Did {D} tell you the band lineup was not booked?", "\"No. {D.He} never discussed the lineup with me. I only handled the lodge and the grounds.\""), .cross("Did the defendant ever sign a final contract with your venue?", "\"No. We had drafts and emails, but no signed contract for the weekend. I cannot say {D.he} had a confirmed booking.\""), .cross("Did you warn the defendant before the date arrived that you would cancel?", "\"Yes. I sent emails about the unpaid balance. I did not know how many passes had been sold, and I did not contact buyers.\"")],
        theory: ("{D} sold a retreat that was never arranged.", "A venue fell through."),
        allocution: "\"I got ahead of myself.\"",
        truths: ("{DL} bought a boat with the pass money.", "{DL} really paid a venue deposit."),
        defendant: [.direct("Did you plan to hold the music retreat?", "\"Yes. I planned it for months. I reached out to the venue several times and paid a deposit to hold the dates.\""), .direct("Why did you spend pass money on a boat?", "\"I should not have. I told myself I could replace it before the retreat, and I was wrong.\""), .direct("Tell the jury how you planned the retreat.", "\"I planned it for months. I contacted venues and agents, picked a lineup, and sold passes to cover the costs of staging and lodging.\""), .direct("What did you do with the money from passes?", "\"Some paid for deposits and expenses. Some I should not have spent. I bought a boat with part of the pass money, and I regret that.\""), .direct("Why did the retreat not happen?", "\"The venue backed out when the balance did not arrive. I had paid a real deposit, and I was scrambling to find a new site when the gate day came.\""), .direct("What did you tell ticket buyers when they asked about the headliners?", "\"That contracts were in progress and the lineup was real. I believed bands would sign, but I never had signed contracts.\""), .cross("You sold 1,300 passes for $360,000 and moved most of it out within days, didn't you?", "\"I did. I used the money for deposits and for things that were not part of the plan. That was a mistake.\""), .cross("No band had signed a contract by opening day, had it?", "\"No. I had talks with some artists, but nothing was signed. I advertised names I should not have.\""), .cross("Will you refund the pass holders?", "\"I want to. I do not have the money now. I know that does not help anyone.\""), .cross("No band ever signed a contract, did they?", "\"That is true. I had talked to agents, but no one had signed. I should have told ticket buyers the lineup was not final.\""), .cross("You spent pass money on a boat, didn't you?", "\"Yes. I told myself I could replace it before the event. I could not, and I know that was a serious mistake.\"")],
        openings: ("{D}, an event organizer, sold 1,300 weekend passes worth $360,000 for a mountain music retreat with named headliners. On opening day the gate was chained, no band had been booked, and most of the money had moved out within days.", "The defense witnesses will explain that {D} reached out to a venue, paid a real deposit, and that the venue backed out when the money came up short."),
        closings: ("Thirteen hundred passes, $360,000, artists who never signed, a chained gate on opening day, and a boat bought with the money. Pass holders were left with nothing.", "An organizer who reached out to a venue, paid a deposit, and lost the booking. The State must prove {D} never meant to hold the event, and a failed plan is not a fraud."),
        timeline: [(-75, "Passes go on sale."), (-20, "{DL} buys the boat."), (0, "Gate day: a chained road."), (21, "Charges.")],
        identified: "Pass sales records.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "I took vacation days I can't get back.",
        doctrines: ["burdenOfProof"])

    static let falseTeamAccusationV1 = SmallCases.make(
        key: "story.falseTeamAccusation",
        category: .publicOrder,
        headlines: ["Athlete Reported a Dorm Stairwell Assault That Key Card Logs Say Never Happened", "Group Chat Shows Plan to Make a Report"],
        law: "falseReport",
        threshold: 7,
        spec: "Gave a false report of a crime to a law enforcement officer, on {DATE}.",
        ages: 18...24,
        victim: false,
        summary: "{D} told campus police on {DATE} that two teammates cornered and hit {D.him} in a dorm stairwell. Key card logs placed both teammates across town and a group chat showed {D} planning the report. {DL} says {D.he} mixed up two bad nights.",
        state: [E(.digital, 3, "Key Card Logs", "The teammates were swiped into a gym across town."), E(.digital, 3, "Group Chat", "{D} writes 'they will pay for cutting me.'"), E(.statement, 2, "Campus Officer", "No injuries matched the account.")],
        defense: [E(.statement, 1, "Mixed Up", "{DL} says two nights blurred together.")],
        role: "Campus police officer",
        exam: [.direct("What did {DL} report on {DATE}?", "\"That two teammates cornered and hit {D} in a dorm stairwell. I took the initial report and began checking the account.\""), .direct("What did the key card logs show?", "\"Both teammates were swiped into a gym across town at the time of the supposed attack. They could not have been in that stairwell.\""), .direct("What did the group chat show?", "\"{DL} wrote 'they will pay for cutting me' in a chat, before the report. It showed planning, not shock.\""), .direct("Did {DL} have injuries?", "\"No. I did not find injuries that matched the account. Nothing consistent with being cornered and hit.\""), .direct("How did the account change?", "\"The details moved as I asked questions. Times and places shifted, which is part of why I checked the logs.\""), .direct("What was the outcome for the teammates?", "\"They were cleared quickly because of the logs. But they were questioned and their families were upset.\""), .cross("Did {DL} seem upset when reporting?", "\"Yes. {D.He} was shaky and tearful. I do not think that was an act, though that is only my impression.\""), .cross("Has {DL} ever been in trouble with police before?", "\"Not that I know. I have no record of any prior report.\""), .cross("Could {DL} have confused two nights?", "\"It is possible. Memory can blur. But the chat message came before the report.\""), .cross("Was there any medical record of a fall?", "\"I understand there was a concussion note from a fall that week. I did not treat it as proof of an attack.\""), .cross("Did you charge {DL}?", "\"I referred it. I did not make that decision. I presented the facts.\"")],
        defenseRole: "Teammate",
        defenseExam: [.direct("How do you know {DL}?", "\"We are on the same team and we room near each other. I see {D} every day.\""), .direct("What happened the week of the report?", "\"{D.He} fell on stairs and hit {D.his} head. {D.He} was dizzy and forgetful for days.\""), .direct("How did {DL} seem?", "\"Foggy. {D.He} lost track of conversations and mixed up days. It worried me.\""), .direct("Did {DL} say anything about the teammates?", "\"{DF} was angry that they had cut {D.him} from the lineup. We talked about it more than once.\""), .direct("Did you think {DL} meant to lie?", "\"No. I think {DF} believed it. I saw how rattled {DF} was.\""), .direct("Would {DL} hurt someone on purpose?", "\"No. {DF} is not that kind of person. {DF} would rather complain than fight.\""), .cross("Were you with {DL} the night of the supposed attack?", "\"No. I was not. I only know {D.his} state afterward.\""), .cross("Did {DL} tell you about the chat?", "\"I saw the message later. It sounded angry.\""), .cross("Were you angry at the two teammates yourself?", "\"A little. They cut people. That is part of why I understand.\""), .cross("Did you tell {DL} to report?", "\"No. I did not.\""), .cross("Can you say {DL} was confused?", "\"I can say {D.he} seemed foggy. I cannot see inside {D.his} head.\"")],
        theory: ("{D} invented an assault to hurt teammates.", "A muddled memory."),
        allocution: "\"I never should have called.\"",
        truths: ("{DL} had been benched because of those two.", "{DL} had a real fall that week and a concussion note."),
        defendant: [.direct("Why did you report that two teammates hit you?", "\"I was confused after a hard week. I had a bad fall and a headache, and I mixed two nights together.\""), .direct("What did you remember at the time?", "\"Being cornered in the stairwell. It felt real. I thought it was the night two teammates shoved me.\""), .direct("What did you mean by 'they will pay for cutting me'?", "\"I was angry that two teammates had pushed me off the lineup. I vented in a chat. I did not plan a false report.\""), .direct("Did you hurt yourself that week?", "\"Yes. I fell and got a concussion note from a clinic. It made my memory fuzzy.\""), .direct("When did you realize you were wrong?", "\"When the officer showed me the logs. I felt sick. I had accused people who were across town.\""), .direct("What would you tell the teammates?", "\"That I truly am sorry. I did not mean to lie. I was not thinking straight.\""), .cross("The chat message came before your report, didn't it?", "\"Yes. I wrote it out of anger. I did not mean it as a plan.\""), .cross("The logs put both teammates across town, don't they?", "\"They do. I was wrong. I was confused.\""), .cross("You had no injuries matching an attack, did you?", "\"No. I just remembered something that was not true.\""), .cross("You changed details as the officer asked, didn't you?", "\"Yes. My memory was shifting. I should have waited before reporting.\""), .cross("Two people were accused because of you, weren't they?", "\"Yes. I know. I feel terrible.\"")],
        openings: ("{D} told campus police that two teammates cornered and hit {D} in a dorm stairwell. Key card logs placed both across town, a group chat showed {D} planning the report, and no injuries matched. The State will show the logs and the chat.", "A concussion note, a foggy week, and a friend who watched {D} lose track of days. {D} did not set out to lie, and a teammate will tell you why."),
        closings: ("Two teammates across town, a chat message before the report, no injuries, and details that shifted. {D} invented an attack and two people were accused.", "{D} had a head injury and a confused week. The State has not proved {D} knowingly told a lie, and a mistaken memory is not a false report."),
        timeline: [(-3, "{DL} is benched."), (0, "Evening: the group chat."), (0, "10 p.m.: the report."), (2, "Logs pulled.")],
        identified: "Key card logs and a group chat.",
        mood: .divided,
        impact: "Teammates stopped speaking to me.",
        doctrines: ["mistakeOfFact"],
        genders: ["D": .female])

    static let deviceOnDeliveryDriverV1 = SmallCases.make(
        key: "story.deviceOnDeliveryDriver",
        category: .violent,
        headlines: ["Courier Chained Into a Fake Bomb Vest and Sent Into a Credit Union", "Prepaid Card Purchase Leads Police to Caller"],
        law: "kidnapping2",
        threshold: 8,
        spec: "Unlawfully confined, restrained and removed {V} by force or threat, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, a package courier, was ambushed at a storage lot on {DATE} and locked into a vest packed with what a caller said was explosive. {V.he} was sent into a credit union with a note. The vest held only clay. {D} was traced through a prepaid phone. {DL} says {D.he} only booked a delivery.",
        state: [E(.digital, 3, "Prepaid Phone Records", "The phone that called {V} was bought with {D}'s card."), E(.physical, 3, "Fake Vest", "Clay and wiring matched a kit found at {D}'s place.", .search), E(.video, 2, "Credit Union Camera", "{V} hands over a note while shaking.")],
        defense: [E(.statement, 1, "Booking", "{DL} says {D.he} only booked a delivery.")],
        role: "Detective",
        exam: [.direct("What was reported on {DATE}?", "\"{V}, a package courier, was ambushed at a storage lot, locked into a vest, told it held explosive, and sent into a credit union with a note.\""), .direct("What did the credit union camera show?", "\"{V} handing the teller a note while visibly shaking. The camera captured the fear.\""), .direct("What was in the vest?", "\"Clay and wiring. It was fake, but {V} did not know that and neither did the credit union staff.\""), .direct("How was {DL} traced?", "\"The prepaid phone that called {V} was bought with {D}'s card. That led us to {DL}.\""), .direct("What did you find at {DL}'s home?", "\"A kit with clay and wiring matching the vest. It was seized in a search.\""), .direct("What did {DL} tell you?", "\"That {D.he} only booked a delivery. {D.He} said the order was an ordinary courier job.\""), .direct("How did you identify the phone that called {V} during the ambush?", "\"Records show the prepaid phone was bought with {DL}'s card, which was reported stolen to the bank before the call. We traced the phone's activity to the storage lot.\""), .cross("Did {V} see the person who locked the vest on?", "\"Only in part. It was a masked figure. {V} cannot identify {DL}.\""), .cross("Was the card ever reported stolen?", "\"I understand a report was made. I do not have the date in front of me.\""), .cross("Are clay and wiring common materials?", "\"Yes. Craft stores sell them. That is why we tied the kit to the vest by its details.\""), .cross("Did {DL} book the delivery in {D}'s own name?", "\"The account was tied to {D.his} card. The name used for the order is under review.\""), .cross("Did anyone see {DL} at the storage lot?", "\"No. I have no witness who placed {DL} there.\"")],
        defenseRole: "Craft store clerk",
        defenseExam: [.direct("What do you sell at the craft store?", "\"Clay, wire, paint, and supplies for models and crafts.\""), .direct("Does {DL} shop there?", "\"Yes. {D} comes in often for clay and wire.\""), .direct("What does {DL} buy?", "\"Modeling clay, floral wire, tape. Hobby things.\""), .direct("Does {DL} make things?", "\"Yes. I have seen {D.his} sculptures. {D.He} is a real craftsperson.\""), .direct("Did you ever see {DL} buy large amounts?", "\"No. Ordinary amounts. Nothing odd.\""), .direct("How would you describe {DL}?", "\"Friendly and calm. I would not guess violence.\""), .direct("How would you describe the supplies {D} buys at your craft store?", "\"Modeling clay, floral wire, and tape. {DF} buys them in small amounts, the way hobbyists do, and I have seen {DF} at the counter many times.\""), .direct("Does the defendant make models or crafts that use clay and wire?", "\"I have seen {D.his} work. {D.He} makes small figures and displays, and once showed me a model village with wire fences and clay houses.\""), .direct("Has anyone else bought the same supplies in large amounts?", "\"Yes. Many customers do, for school projects and hobbies. Clay and wire are sold to anyone, and we do not track who buys what.\""), .direct("Did you ever see the defendant buy anything that looked unusual or dangerous?", "\"No. Only modeling clay, floral wire, and tape. {D.He} was always polite at the counter and never bought anything that made me suspicious or worried about what it would be used for.\""), .direct("How well do you know the defendant?", "\"I have known {DF} as a regular customer for years. We chat about hobbies when {DF} comes in, and I have never seen {DF} angry, rude, or aggressive with anyone.\""), .cross("Can anyone buy clay and wire?", "\"Yes. Anyone. No questions asked.\""), .cross("Did {DL} buy anything the week of the crime?", "\"I would have to check. I believe so.\""), .cross("Do you know anything about the vest?", "\"No. I only know what {D.he} bought from me.\""), .cross("Did {DL} ever talk about explosives?", "\"No. Never.\""), .cross("Do you know where {DL} was that day?", "\"No. I was working.\"")],
        theory: ("{D} turned a courier into a hostage and a robber.", "Only a booking."),
        allocution: "\"I can't take it back.\"",
        truths: ("{DL} searched the credit union's hours the night before.", "The card was reported stolen to the bank before the call."),
        defendant: [.direct("Did you book a delivery that day?", "\"Yes. I booked a courier to bring a package. I used my own card and my own name. That was all.\""), .direct("Did you lock a vest on {V}?", "\"No. I have never done anything like that. I was not at the storage lot.\""), .direct("What about the prepaid phone?", "\"My card was used to buy it. I did not buy it. I reported the card stolen to the bank.\""), .direct("Why do you own clay and wiring?", "\"I do crafts. Clay, wire, and glue are in my home. It is a hobby.\""), .direct("Where were you that day?", "\"At work. I have people who saw me. I was not at the lot.\""), .direct("How has this affected you?", "\"Horrified. No one deserves that. I am cooperating fully.\""), .direct("Why did you search the credit union's hours the night before?", "\"I was planning an errand and I was checking several places for hours. I did not think of it again until deputies asked me about it.\""), .cross("The phone was bought with your card, wasn't it?", "\"Yes. That is what they say. My card was misused.\""), .cross("A kit matching the vest was found in your home, wasn't it?", "\"Craft supplies matched. They are common. It was not a bomb kit.\""), .cross("You booked the very delivery that lured {V}, didn't you?", "\"I booked a delivery. I did not know what it would become.\""), .cross("You searched the credit union's hours the night before, didn't you?", "\"I search many businesses. I have no explanation beyond that.\""), .cross("You reported the card stolen only after the crime, didn't you?", "\"Before, I believe. The bank has the record.\"")],
        openings: ("A courier was ambushed at a storage lot, locked into a vest {V.he} was told held explosive, and sent into a credit union with a note. The vest held only clay. The phone that called {V} was bought with {D}'s card. The State will show the records.", "Clay and wire are craft supplies sold to anyone, and a card can be misused. A clerk who knows {D} as a craftsperson will tell you what {D} buys and why."),
        closings: ("A courier forced into a vest, a prepaid phone bought with {D}'s card, a search of the credit union's hours the night before, and a kit of clay and wire at {D}'s home. Together they point to {D}.", "Clay and wire are craft supplies sold to anyone, and a stolen card can be misused. The State has not proved {D} placed that vest, and a hobbyist's supplies are not evidence of a plot."),
