    static let lotteryClerkInsiderV1 = SmallCases.make(
        key: "story.lotteryClerkInsider",
        category: .whiteCollar,
        headlines: ["Gaming Commission Analyst Spotted Unsold Jackpot Ticket Through Retailer Data", "$1.8 Million Claimed by Roommate"],
        law: "falsePretenses100k",
        threshold: 8,
        spec: "Obtained over $100,000 by false pretenses from {V}, a state lottery, on or about {DATE}.",
        ages: 22...60,
        victim: true,
        summary: "{D}, a lottery data analyst, saw in terminal data that a $1.8 million scratch ticket was still sitting unsold in one store, then sent a roommate to buy it before the next shipment. The claim came in on {DATE}. {DL} says the roommate chose the ticket randomly.",
        state: [E(.digital, 3, "Terminal Data Query", "{D} queried that store's inventory the day before."), E(.video, 3, "Store Camera", "The roommate asks for one ticket by position."), E(.document, 2, "Claim Form", "Signed by the roommate.")],
        defense: [E(.statement, 1, "Random Pick", "{DL} says the pick was random.")],
        role: "Lottery auditor",
        exam: [.direct("What does the store camera show?", "\"{D}'s roommate asking the clerk for one ticket by position, the very ticket that turned out to be the winner.\""), .direct("How was the prize claimed?", "\"On a claim form signed by the roommate on the date in question. The claim came in soon after the purchase.\""), .direct("Describe your work as a lottery auditor.", "\"I audit lottery data and claims. I review ticket inventories, sales patterns, and claim forms to make sure prizes are won fairly.\""), .direct("What did you find in the terminal data?", "\"{DL}, an analyst, queried one store's inventory the day before. The query showed a $1.8 million scratch ticket still unsold in that store.\""), .direct("What happened next?", "\"The next day, {DL}'s roommate asked a clerk for a ticket by position. The roommate signed the claim form for the prize on the date it was filed.\""), .direct("What did you do after you saw the claim form?", "\"I pulled the terminal logs and traced every inventory query on that store. The only query before the claim was the analyst's, run the night before.\""), .cross("{D} says the roommate chose the ticket randomly, doesn't {D.he}?", "\"Yes. A convenience store owner says many customers pick spots, so that is not unusual.\""), .cross("Did the defendant tell the roommate which ticket to ask for?", "\"I have no recording of that. I only have the query and the camera.\""), .cross("Was the defendant's query part of a scheduled monthly pull?", "\"Part of {D.his} job involves monthly pulls. But this query was run the day before the purchase, and it focused on one store.\""), .cross("Can customers legally choose a position on the roll?", "\"Yes. Many customers ask for a ticket by position. A request by itself does not break any rule, and I cannot say it was not random.\""), .cross("You cannot say whether the roommate picked the ticket at random, can you?", "\"I can say the camera shows a request by position, but I cannot say how the roommate chose it.\"")],
        defenseRole: "Convenience store owner",
        defenseExam: [.direct("Can customers pick a particular spot on the scratch ticket roll?", "\"Many do. Customers ask for the third from the left or the fifth down, and I hand it over.\""), .direct("Did this customer pick a spot in that way?", "\"Yes. The customer asked for a ticket by position, as many do, and I thought nothing of it.\""), .direct("How common is it for customers to pick a spot?", "\"Very common. Some people have lucky spots, and they ask for them every time they come.\""), .direct("What can you tell us about your store?", "\"I own a convenience store that sells scratch tickets. I stock rolls from the lottery commission, and I see customers choose tickets every day.\""), .direct("How do customers pick tickets from a roll?", "\"Many ask for a spot, like the third from the end. Some say a lucky number. It is common, and I do not think twice when it happens.\""), .direct("Do you remember this customer?", "\"I remember a customer asking for a ticket by position. It was a normal request, and I did not know the ticket was a winner until later.\""), .cross("Did you know the customer was a roommate of a lottery analyst?", "\"No. I did not know anything about that. It was just a customer buying a ticket.\""), .cross("Did the customer ask for that exact ticket by position every time?", "\"I do not know. I only remember this one time, since the ticket won.\""), .cross("Did you see the customer talk to anyone before buying?", "\"No. I did not notice. I was ringing up other customers.\""), .cross("Did anything about that purchase seem unusual to you?", "\"No. It looked like any other purchase. I did not know who the customer was, and I did not know about any data query.\""), .cross("Could someone tell which ticket was a winner by looking at the roll?", "\"No. The ticket is covered and the roll is mixed. A buyer would have to guess, or use inventory data to guess.\"")],
        theory: ("{D} used inside data to win a jackpot.", "A random pick."),
        allocution: "\"I made a terrible mistake.\"",
        truths: ("{DL} paid the roommate's rent for a year before the claim.", "{DL}'s query was part of a scheduled monthly pull."),
        defendant: [.direct("Did you rig the lottery claim?", "\"No. I did not rig anything. My roommate chose the ticket randomly, and the win was luck.\""), .direct("Why did you query that store's inventory?", "\"It was part of a scheduled monthly pull. I run those queries as part of the job, and I did not single out that store.\""), .direct("Did you pay your roommate's rent?", "\"I covered the rent for a year before the claim. That was a favor between roommates and had nothing to do with the ticket.\""), .direct("Describe your work as a data analyst.", "\"I work with lottery terminal data. I run monthly pulls on inventory and sales, and I look for problems in how tickets are distributed.\""), .direct("How did your roommate come to buy that ticket?", "\"My roommate bought a ticket the way anyone does. The pick was random, and I did not tell my roommate which ticket to ask for.\""), .direct("Why did you cover your roommate's rent for a year?", "\"My roommate was struggling. I paid the rent as a favor between friends, long before any prize, and I did not expect anything in return.\""), .cross("You saw a $1.8 million ticket sitting unsold the day before, didn't you?", "\"The data showed all kinds of tickets. I did not focus on that one. I do not remember it.\""), .cross("Your roommate then asked for one ticket by position, didn't they?", "\"Yes. Many people do. It was not my instruction.\""), .cross("You saw the unsold $1.8 million ticket in the data, didn't you?", "\"I saw inventory for many stores. I did not focus on that ticket, and I did not know it was still unsold until after the claim.\""), .cross("Your roommate signed the claim, didn't your roommate?", "\"Yes. My roommate bought the ticket and claimed the prize. I did not claim it, and I did not ask for a share.\""), .cross("You paid your roommate's rent for a year before the claim, didn't you?", "\"Yes. My roommate was out of work. It was a friendship, not a scheme, and I had no idea a prize ticket was in that store.\"")],
        openings: ("A lottery data analyst, {D}, queried one store's inventory the day before and saw a $1.8 million scratch ticket still unsold. {D}'s roommate then bought one ticket by position and claimed the prize.", "Weigh the defense proof, which will show that {D}'s query was part of a scheduled monthly pull, that customers often pick spots, and that the roommate's choice was luck."),
        closings: ("An insider query, a roommate buying one ticket by position the next day, and a claim for $1.8 million. {D} paid the roommate's rent for a year first.", "A routine monthly pull and a customer who picked a spot, as many do. The State must prove {D} used inside data to direct the purchase."),
        timeline: [(-1, "{D} runs the inventory query."), (0, "The roommate buys the ticket."), (6, "The claim is filed."), (50, "The audit.")],
        identified: "A data query log.",
        aggravating: ["The defendant took advantage of a position of trust or confidence", "The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["mistakeOfFact"],
        genders: ["D": .male])

    static let mugshotRemovalFeesV1 = SmallCases.make(
        key: "story.mugshotRemovalFees",
        category: .whiteCollar,
        headlines: ["Arrest Photo Site Charged Fee to Delete Pages Even After Dismissals", "Cleared Customers Billed $350"],
        law: "extortion",
        threshold: 7,
        spec: "Threatened to continue publication of {V}'s arrest photo unless paid $350, on {DATE}.",
        ages: 22...60,
        victim: true,
        summary: "{D} ran a site that copied arrest photos from jail rosters. On {DATE}, {V} got a letter asking $350 to delete a page, though {V}'s case had been dropped. {DL} says the fee covered a service.",
        state: [E(.document, 3, "Fee Letter", "'Pay $350 or the page stays.'"), E(.document, 3, "Dismissal Notice", "{V}'s case was dropped."), E(.digital, 2, "Payment Ledger", "Hundreds of $350 payments.")],
        defense: [E(.statement, 1, "Cleanup Service", "{DL} says the fee paid for cleanup work.")],
        role: "Person pictured",
        exam: [.direct("What did you receive in the mail?", "\"A letter asking $350 to delete a page about me from {D}'s site. It said, 'Pay $350 or the page stays.'\""), .direct("What was the status of your case?", "\"It was dropped. A dismissal notice confirms that. The charges were gone before the letter came.\""), .direct("What did the payment ledger show?", "\"Hundreds of $350 payments from other people in the same position.\""), .direct("What can you tell us about your arrest and what happened afterward?", "\"I was arrested once, and the charge was later dropped. I thought that was behind me until I found a page with my photo on {D.his} site.\""), .direct("How did you learn about the page?", "\"A letter arrived in the mail saying 'Pay $350 or the page stays.' It was from {D.his} site, and it listed a way to pay.\""), .direct("How did the page affect you?", "\"I worried about my job and my family. The page showed my arrest photo and name, even though the case was dropped, and I could not stop thinking about it.\""), .cross("{D} says the fee covered a service, doesn't {D.he}?", "\"Yes. A payment processor says the site disclosed the fee on a page. I cannot argue.\""), .cross("Were the photos from public rosters?", "\"Yes. The photos came straight from public jail rosters. I understand that.\""), .cross("Did you send the dismissal paper to the defendant?", "\"Yes. I sent a copy of the dismissal notice with a removal request. I got no answer, and the page stayed up.\""), .cross("Did you pay the $350?", "\"No. I did not pay. I felt it was unfair to pay for something that should not have been there, and I contacted deputies.\""), .cross("You paid nothing to the site, did you?", "\"No. I refused to pay, and I contacted a lawyer. The page stayed up for months, and I could not get a job interview.\"")],
        defenseRole: "Payment processor rep",
        defenseExam: [.direct("Were the payments to {D}'s site ever disputed?", "\"A few. Some customers disputed charges, but most payments went through without any issue at all.\""), .direct("Did the site disclose the fee for removal?", "\"On a page, yes. The fee was listed on a page of the site, though not on the page that had the photo.\""), .direct("What was your role in handling the payments?", "\"I handle payment processing for sites like this one. I process payments, and I do not review the content.\""), .direct("Tell us about your work at the payment processor.", "\"I work for a payment processor. I review merchant accounts, handle disputes, and keep records of payments made through the processor's system.\""), .direct("What did you see about payments to the defendant's site?", "\"Hundreds of payments of $350 over time. A few were disputed, but most went through without any complaint to the processor.\""), .direct("Did the site disclose its fee?", "\"On a page, yes. The fee was listed. We required merchants to post pricing, and {D}'s page met that rule when I reviewed it.\""), .cross("Did you see letters sent to people whose cases were dismissed?", "\"No. I do not see the letters. I only see the payments and the disputes.\""), .cross("Would a person whose case was dismissed feel pressured to pay?", "\"Probably, yes. A page that stays up can feel like a threat. I can see why.\""), .cross("How many disputes did your company get on this site?", "\"A few. I do not have the exact number at hand. It was small compared to the payments.\""), .cross("Did you review whether the defendant ignored removal requests with dismissal papers?", "\"No. That is outside what I review. I only see payments and disputes, not what happens between a person and the site.\""), .cross("How many disputes did you receive about the defendant's account?", "\"A few. I do not have the exact number with me. Some customers said they did not understand the charge.\"")],
        theory: ("{D} charged people to stop publishing their photos.", "A cleanup service."),
        allocution: "\"I did not see the harm.\"",
        truths: ("{DL} ignored removal requests that came with dismissal papers.", "The photos came straight from public rosters."),
        defendant: [.direct("Did you threaten {V} with a page that would stay up?", "\"No. I offered a removal service. The fee covered the cost of removing a page on request.\""), .direct("Where did the photos on your site come from?", "\"Straight from public jail rosters. I copied them, and I did not make up any information.\""), .direct("Did you ignore removal requests with dismissal papers?", "\"Some. I did not answer all of them. The volume was high, and I did not read every one.\""), .direct("Tell the jury how your site worked.", "\"I copied arrest photos from public jail rosters and posted them in a searchable database. The photos were public records, and I did not alter them.\""), .direct("What was the $350 fee for?", "\"I offered a removal service. Some people paid to have their pages cleaned up, and the fee covered the work of taking down and monitoring pages.\""), .direct("What did you do when people sent dismissal papers?", "\"I did not always respond. I received many requests, and I treated the removal fee as the normal way to handle them.\""), .cross("The letter said 'Pay $350 or the page stays.' How is that not a threat?", "\"It was a plain statement of the service. I did not mean it as a threat to anyone.\""), .cross("{V}'s case had been dismissed, hadn't it?", "\"Yes. I did not check. I should have removed the page without a fee.\""), .cross("Hundreds of people paid $350. Doesn't that show pressure?", "\"Many chose the service. I understand that it can feel like pressure.\""), .cross("You ignored removal requests that came with dismissal papers, didn't you?", "\"Often, yes. I should have removed those pages for free. I did not think that I was obligated to, and I see it differently now.\""), .cross("The letter said Pay $350 or the page stays, didn't it?", "\"Yes. That is how the letter was worded. I understand how it sounds, and I should have written it differently.\"")],
        openings: ("{D} ran a site that copied arrest photos from jail rosters, and sent {V} a letter saying 'Pay $350 or the page stays' even though {V}'s case had been dropped. Hundreds of people have paid the same fee.", "Jurors will hear that the photos came from public rosters, that the fee was disclosed on the site, and that {D} offered a removal service and made no threat."),
        closings: ("'Pay $350 or the page stays,' sent to a person whose case was dropped. Hundreds paid, and that is extortion by a website.", "A site that copied public records and charged for taking pages down. The State must prove {D} made an unlawful threat, and a fee for a service is not extortion."),
        timeline: [(-45, "The page goes live."), (0, "The letter."), (20, "{V} reports."), (80, "Charges.")],
        identified: "A fee letter.",
        mood: .divided,
        impact: "A landlord saw it and turned me away.",
        doctrines: ["relevance"])

    static let laneClosurePaybackV1 = SmallCases.make(
        key: "story.laneClosurePayback",
        category: .publicOrder,
        headlines: ["County Manager's Aide Staged Road Work to Choke a Rival Town's Main Street", "Cones With No Crew"],
        law: "obstruction",
        threshold: 7,
        spec: "Willfully obstructed justice and public duty through false orders, on {DATE}.",
        ages: 28...60,
        victim: false,
        summary: "{D}, an aide to a county manager, sent a false work order on {DATE} to close the main street of a rival town for 'drainage repair.' No crew ever came. An email thread shows the aim. {DL} says it was a real repair job.",
        state: [E(.digital, 3, "Email Thread", "'Let their main street sit empty a week.'"), E(.document, 3, "Work Order", "No contractor was ever assigned."), E(.statement, 2, "Road Crew Supervisor", "'We got no job number.'")],
        defense: [E(.document, 1, "Drainage Complaint", "A resident's complaint about the street.")],
        role: "Road crew supervisor",
        exam: [.direct("What did you receive in the work order?", "\"A false work order sent by {D}, an aide to a county manager, to close the main street of a rival town for 'drainage repair.'\""), .direct("What did the road crew supervisor receive?", "\"No job number. No crew was ever assigned, and no contractor was ever sent to do any drainage repair.\""), .direct("What does the email thread show?", "\"'Let their main street sit empty a week.' The thread shows the aim of the closure.\""), .direct("What can you tell us about your job as a road crew supervisor?", "\"I supervise a county road crew. I schedule repairs, assign jobs by number, and make sure each closure has a real work order behind it.\""), .direct("What did you receive from {D}?", "\"A work order to close a rival town's main street for drainage repair. It came without a contractor and without a job number.\""), .direct("What did your records show about crews that week?", "\"No job number was assigned and no crew was sent. I saw no record of any repair on that street that week.\""), .cross("{D} says it was a real repair job, doesn't {D.he}?", "\"A drainage complaint was real and still open. A town clerk confirms that. I cannot argue.\""), .cross("Was a repair scheduled that week?", "\"Not that week. The clerk says nothing was scheduled.\""), .cross("Did {D} say anything about the rival town?", "\"I heard {DL} said the town needs a lesson. I did not hear it myself.\""), .cross("Was drainage a real concern on that street?", "\"A resident had complained about drainage, and I know the complaint was open. But that does not explain a week-long closure without a crew.\""), .cross("Did the defendant tell you the closure was meant to hurt the town?", "\"No. {D.He} never told me that. I only learned of that later from an email thread about letting the main street sit empty.\"")],
        defenseRole: "Town clerk",
        defenseExam: [.direct("Was drainage a known issue on the main street?", "\"Yes. We had a drainage complaint on that street, and it was real. It was still open at the time.\""), .direct("Was a repair scheduled for that street in that week?", "\"Not that week. A repair was needed, but nothing was on the calendar for the days in question.\""), .direct("Who files the work orders for road closures at the county?", "\"The manager's office, usually. An aide like {D} can send a work order on the manager's behalf.\""), .direct("Please tell us about your job as a town clerk.", "\"I serve as clerk for the town. I keep records, take complaints, and handle notices about road closures and permits that affect our streets.\""), .direct("What do you know about the drainage complaint on main street?", "\"A resident complained about drainage, and the complaint was still open. It had been logged weeks earlier, and no repair was done when it was logged.\""), .direct("How is a road closure supposed to be filed?", "\"The county files a work order with a job number and a contractor, and the town receives a notice. This time, we received a notice with no job number.\""), .cross("Was a contractor ever assigned to the drainage repair?", "\"No. No contractor was assigned. The work order went out, and nothing followed after it.\""), .cross("Would you close a main street without a crew assigned?", "\"No. I would not. A closure without a crew makes no sense and creates a mess for the town.\""), .cross("Did you hear {D} say anything about the rival town?", "\"I heard that {D.he} said the town needs a lesson. I did not hear it myself, only from a coworker.\""), .cross("Did the town receive a crew that week?", "\"No. No crew came. The street was closed, and the town's businesses had almost no customers for the week.\""), .cross("Did the defendant contact you about the drainage repair before the closure?", "\"No. I was not contacted. I learned about the closure when the notice arrived, and I had no warning.\"")],
        theory: ("{D} faked road work to punish a town.", "A real drainage job."),
        allocution: "\"It was petty and I regret it.\"",
        truths: ("{DL} told a coworker the town 'needs a lesson.'", "The drainage complaint was real and still open."),
        defendant: [.direct("Did you close the rival town's main street out of spite?", "\"No. I sent the work order for a real drainage problem. The complaint was real and still open.\""), .direct("Why was no crew assigned?", "\"The scheduling fell through. I assumed a crew would be found, and I did not follow up closely.\""), .direct("What about the email, 'Let their main street sit empty a week'?", "\"It was a bad joke between colleagues. I did not mean it. The job was real.\""), .direct("Describe your job as an aide for the jury.", "\"I work for a county manager. I handle correspondence, schedules, and requests from towns, and I send work orders when a manager asks me to.\""), .direct("Why did you send the work order?", "\"There was a real drainage complaint on that street. I wanted the repair scheduled, and I sent the order to close the street for the work.\""), .direct("What did you mean by the line about letting the street sit empty?", "\"It was a bad joke in an email. I wrote it in frustration after the town rejected a deal, and I did not mean it as a plan.\""), .cross("The work order was sent with no contractor and no job number, wasn't it?", "\"Yes. It was sent before the paperwork was done. That was my mistake.\""), .cross("A rival town's main street sat closed with no repair. Who is responsible?", "\"I am. I should have checked that a crew was assigned first.\""), .cross("You told a coworker the town needs a lesson, didn't you?", "\"I said something like that. I was angry at the time, and I should not have said it. It does not mean I faked the order.\""), .cross("No crew or contractor was ever assigned, was one?", "\"No. The scheduling fell through. I assumed a crew would be assigned, and I did not follow up the way In hindsight, yes.\""), .cross("Nobody from the road crew was assigned to the job, were they?", "\"No one was assigned. I sent the work order and assumed the crew would pick it up. I should have followed up.\"")],
        openings: ("{D}, an aide to a county manager, sent a work order to close the main street of a rival town for 'drainage repair.' No crew or contractor was ever assigned, and an email thread says 'Let their main street sit empty a week.'", "The defense evidence will establish that the drainage complaint was real and still open, and that {D}'s order was an ill-planned repair, not payback."),
        closings: ("A work order with no crew, no contractor, and no job number, and an email thread that states the aim. The street was closed to punish a rival town.", "A real drainage complaint and a sloppy work order. The State must prove {D} closed the street for payback, and a bad joke in an email is not proof."),
        timeline: [(-10, "The rival town rejects a deal."), (0, "The order goes out."), (0, "The street empties."), (45, "The emails leak.")],
        identified: "An email thread.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let neighborsWatchStabbingV1 = SmallCases.make(
