        spec: "Knowingly obtained and used the identifying information of a deceased relative, to avoid legal processes and obtain benefits, on or about {DATE}.",
        ages: 40...70,
        victim: false,
        summary: "{D} used a dead sibling's name and number for years to collect $120,000 in disability checks and renew a license. A fingerprint check at a licensing office on {DATE} exposed it. {DL} says the sibling wanted the name used.",
        state: [E(.forensic, 3, "Fingerprint Card", "Prints match {D}'s old arrest card, not the dead sibling."), E(.document, 3, "Disability Payments", "Paid in the dead sibling's name."), E(.document, 2, "Death Certificate", "The sibling died long ago.")],
        defense: [E(.statement, 1, "Deathbed Wish", "{DL} says the sibling asked for it.")],
        role: "Licensing investigator",
        exam: [.direct("What did your investigation start with?", "\"A fingerprint check at a licensing office on {DATE}. The prints did not match the name on the license.\""), .direct("What did the fingerprint card show?", "\"The prints match {D}'s old arrest card, not the sibling whose name was on the file.\""), .direct("What does the death certificate show?", "\"That the sibling died long ago, many years before the checks and license renewals began.\""), .direct("What payments were made?", "\"$120,000 in disability checks in the dead sibling's name over a period of years.\""), .direct("How was the name used?", "\"To collect checks and renew a license. The identity was used as if the sibling were alive.\""), .direct("What did {DL} say when confronted?", "\"That the sibling had wanted the name used. I recorded that statement.\""), .direct("What did the licensing office's fingerprint check reveal about the person who renewed the license?", "\"The prints did not match the name on the license. They matched {DL}'s old arrest card, which showed that the identity of the dead sibling had been used for years.\""), .cross("Is there any record of the sibling's wish?", "\"Not in writing. Only an aunt who says the aunt heard it.\""), .cross("Did {DL} try to hide from you?", "\"No. {D.He} came in, gave prints, and talked. {D.He} did not run.\""), .cross("Did {DL} need the disability payments?", "\"I do not know. I cannot speak to need.\""), .cross("Did the agency check the identity at enrollment?", "\"The identity was accepted on documents. Verification was weak, which I admit.\""), .cross("Did {DL} use the name on anything else?", "\"The license and the checks. Those are what I found.\"")],
        defenseRole: "Aunt",
        defenseExam: [.direct("How are you related to {DL}?", "\"I am the aunt of both {D} and the sibling. I helped raise them.\""), .direct("Did the sibling say something about the name?", "\"Yes. Near the end, the sibling said to let {DF} use the name. I heard it.\""), .direct("Where were you when you heard it?", "\"At the bedside. It was quiet. Only a few of us.\""), .direct("What did {DL} say?", "\"{D.He} cried and said no, then agreed. I remember it.\""), .direct("Did you know about the checks?", "\"I did not. I only knew about the name.\""), .direct("How are you coping with what happened?", "\"I love {DF}. I do not think {DF} meant to steal.\""), .direct("What did the sibling say about the name when you were at the bedside?", "\"The sibling said to let {DF} use the name and to keep it going. I heard it clearly, and I was in the room with a few other relatives at the time.\""), .direct("How did {D} react to hearing that wish?", "\"{D.He} cried and held the sibling's hand. {D.He} said nothing at the time, and I think {D.he} took it as a promise to keep for life.\""), .direct("Did you ever see the defendant act as if the name was a secret?", "\"No. {D.He} used the name openly with family and neighbors for years. {D.He} never hid it from us, and none of us questioned it until the fingerprint check.\""), .cross("Was the wish written down?", "\"No. Only spoken.\""), .cross("Were there other witnesses?", "\"Maybe. I do not recall who.\""), .cross("Did the sibling mention disability checks?", "\"No. Never.\""), .cross("Did anyone tell {DL} it was legal?", "\"No. No one did.\""), .cross("Do you think the name should receive benefits?", "\"No. It would not.\"")],
        theory: ("{D} lived on a dead sibling's identity to collect money.", "A promise at a deathbed."),
        allocution: "\"I got in too deep.\"",
        truths: ("{DL} had an old warrant under {DL}'s own name.", "The aunt heard the sibling's wish."),
        defendant: [.direct("Why did you use your sibling's name?", "\"My sibling asked me to, near the end. I took it as a wish to carry the name on.\""), .direct("Did you collect disability checks?", "\"Yes, in that name. I thought it was part of carrying on. I did not understand it was illegal.\""), .direct("Did you renew a license?", "\"Yes. Under that name. I was living as that person in some ways.\""), .direct("Why did you keep going for years?", "\"Nobody questioned it. I got comfortable. I did not think about the law.\""), .direct("What were you afraid of?", "\"An old problem under my own name. I did not want to face it.\""), .direct("Do you regret it?", "\"Yes. I should have told the truth. I apologize.\""), .direct("What did your sibling say at the end about using the name?", "\"My sibling told me near the end to keep the name and use it. I did not want it to be lost, and I thought I was honoring a wish.\""), .direct("Why did you keep using the name for so many years afterward?", "\"Once I started, it became my life. I got used to it, and I was afraid of what would happen if I stopped, including an old warrant under my own name.\""), .cross("Your sibling died long before the checks began, didn't they?", "\"Yes. They did. I know that.\""), .cross("You signed forms in your sibling's name, didn't you?", "\"Yes. I did. It was wrong.\""), .cross("$120,000 is a lot of checks, isn't it?", "\"It adds up over years. I did not count.\""), .cross("Your own prints are on file under your own name, aren't they?", "\"Yes. They are. I did not hide forever.\""), .cross("No written record of this wish exists, does it?", "\"No. It was spoken. I cannot prove it.\"")],
        openings: ("{D} used a dead sibling's name and number for years to collect $120,000 in disability checks and renew a license, until a fingerprint check exposed it. The State will show the prints, the payments, and the death certificate.", "A deathbed wish, spoken to those at the bedside, and an aunt who heard it. {D} never hid the name from the family and says the sibling asked for it."),
        closings: ("A dead person's name, $120,000 in disability checks, and a license renewed over many years. Fingerprints showed who was really using that name, and the use was a lie every time it was renewed.", "A deathbed wish that an aunt heard, and a name kept openly for many years. The State must prove {D} meant to defraud, and a promise to a dying sibling is not a plan to steal."),
        timeline: [(-8000, "The sibling dies."), (-6500, "{D} starts using the name."), (0, "The fingerprint check."), (25, "Charges.")],
        identified: "A fingerprint check.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male, "V": .male])

    static let droneDropAtTheYardV1 = SmallCases.make(
        key: "story.droneDropAtTheYard",
