        summary: "A drone struck a fence at a county jail on {DATE} and dropped a pouch of hydrocodone pills. Its serial number led to a hobby shop sale to {D}. {DL} says the drone was stolen from a truck weeks before.",
        state: [E(.physical, 3, "Drone Wreck", "Serial number from a unit sold to {D}.", .search), E(.forensic, 3, "Pouch Contents", "Hydrocodone pills in a heat-sealed bag."), E(.digital, 2, "Phone Messages", "'Be ready at the north fence.'")],
        defense: [E(.document, 1, "Theft Report", "{DL} filed a theft report for the drone.")],
        role: "Jail officer",
        exam: [.direct("What happened at the jail on {DATE}?", "\"A drone struck our fence and dropped a pouch. Inside, in a heat-sealed bag, were hydrocodone pills.\""), .direct("How did you trace the drone?", "\"The serial number on the wreck led to a unit sold at a hobby shop. The sale record names {D}.\""), .direct("What did the messages say?", "\"'Be ready at the north fence.' That is the area where the pouch landed, which is why I took the message seriously.\""), .direct("Why does the heat seal matter?", "\"It shows packaging for delivery. Someone prepared that pouch to survive a drop.\""), .direct("What did you recover?", "\"The wreck, the pouch, and the pills. The serial number was readable on the frame.\""), .direct("What did {DL} tell investigators?", "\"That the drone was stolen from a truck weeks earlier. {D.He} filed a theft report.\""), .direct("How did the serial number on the drone lead you to {D}?", "\"The serial number on the wreck led to a hobby shop sale record showing {DL} bought the drone. The pills were in a heat-sealed bag, which a hobbyist would not normally use.\""), .cross("Did you see {DL} fly the drone?", "\"No. I found the wreck. I did not see anyone at the controls.\""), .cross("Was the theft report real?", "\"A report exists. I cannot say when it was made without checking.\""), .cross("Can anyone buy that model of drone?", "\"Yes. Many hobby shops sell it. The serial links it to {D.his} purchase, not to the flight.\""), .cross("Did you identify the person who sent the message?", "\"No. The number is not confirmed to be {DL}'s.\""), .cross("Did any inmate name {DL}?", "\"No. Not in my presence.\"")],
        defenseRole: "Hobby shop clerk",
        defenseExam: [.direct("What do you do at the hobby shop?", "\"I sell and register drones. I keep sale records and serial numbers.\""), .direct("Did you sell {DL} a drone?", "\"Yes. A mid-size model. The sale record shows the serial.\""), .direct("What was {DL} like as a customer?", "\"Interested and knowledgeable. {D} asked about range and battery.\""), .direct("Do customers report theft?", "\"Sometimes. People come back and say a drone was taken.\""), .direct("Did {DL} come back about a theft?", "\"I recall {D.he} calling about it. I do not remember when.\""), .direct("Do you know what {DL} used it for?", "\"Photography, I thought. {D.He} showed me photos once.\""), .direct("Tell us what you remember about selling the drone to {D}.", "\"I remember the sale clearly. It was a mid-size model, and {D.he} asked detailed questions about range and battery life like a serious hobbyist would.\""), .direct("Did the defendant ever say anything that made you suspicious?", "\"No. {D.He} asked about flying range for photography, and we talked about places to fly. I have not seen anything that made me suspect anything wrong.\""), .direct("Do drone owners often have their equipment stolen?", "\"Yes. Customers tell me about break-ins at their trucks and garages. Drones and equipment are targets, and I have registered several that were later reported stolen.\""), .cross("Did {DL} say it was stolen before the crash?", "\"I do not recall. I know of the call, not the date.\""), .cross("Can drones be modified to carry loads?", "\"Yes. Many can. Anyone can attach a pouch.\""), .cross("Is the serial number unique?", "\"Yes. Each unit has one.\""), .cross("Did {DL} show any concern?", "\"Not that I noticed.\""), .cross("Did you check for a police report?", "\"No. That is not my role.\"")],
        theory: ("{D} sent pills into a jail by air.", "A stolen drone."),
        allocution: "\"I should have said no.\"",
        truths: ("{DL} filed the theft report only after the crash.", "{DL}'s truck really was broken into that month."),
        defendant: [.direct("Did you buy that drone?", "\"Yes. I bought it for hobby flying. It was a nice model.\""), .direct("What happened to it?", "\"It was stolen from my truck weeks before the jail incident. I reported the theft.\""), .direct("When did you file the report?", "\"After I learned it was used. I should have filed sooner. I thought it was lost.\""), .direct("Did you send a drone to the jail?", "\"No. I would never. I was home, and I never touched that drone that day.\""), .direct("What about the message about the north fence?", "\"I did not send it. I do not know who did.\""), .direct("How do you feel?", "\"Frustrated and scared. I am being blamed for something someone did with my property.\""), .direct("Walk us through what happened to the drone after you bought it.", "\"I used it for hobby flying for a while. Then my truck was broken into that month, and the drone was stolen along with some other equipment.\""), .direct("Why did you wait until after the crash to file a theft report?", "\"I thought I would never see it again and did not think a report would help. When I learned it had been used at the jail, I filed right away.\""), .cross("The serial number leads to your purchase, doesn't it?", "\"Yes. It is my drone. I did not fly it.\""), .cross("You filed the theft report after the crash, didn't you?", "\"Yes. I did. I see how that looks.\""), .cross("Your truck was broken into, you say?", "\"Yes. That month. I have no photo.\""), .cross("You have no witness to the break-in, do you?", "\"No. Only the report.\""), .cross("Hydrocodone pills are worth a lot in a jail, aren't they?", "\"I imagine so. I have no part in it.\"")],
        openings: ("A drone struck a county jail fence and dropped a heat-sealed pouch of hydrocodone pills. Its serial number led to a hobby shop sale to {D}, and a message told someone to 'be ready at the north fence.' The State will show the wreck and the sale.", "A drone can be stolen. {D} says that is exactly what happened weeks earlier and filed a report, and the shop that sold it will tell you how often this occurs."),
        closings: ("The wreck carries a serial number from a drone sold to {D}, the pouch holds pills, and a message names the north fence. The trail runs to {D}.", "A serial number shows who bought a drone, not who flew it. {D} says it was stolen. The State has not proved {D} sent it to the jail."),
        timeline: [(-30, "The truck break-in."), (0, "The drone hits the fence."), (2, "The theft report."), (14, "Search of {DL}'s home.")],
        identified: "A drone serial number.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let riggedMidwayGameV1 = SmallCases.make(
        key: "story.riggedMidwayGame",
        category: .whiteCollar,
        headlines: ["Basketball Hoops at County Fair Booth Measured Smaller Than Posted", "Players Lose $6 a Try at a Game Built to Reject Shots"],
