        spec: "Obtained money from others by false pretenses, on or about {DATE}.",
        ages: 21...65,
        victim: false,
        summary: "{D}, a game booth operator, ran a hoop shot game on {DATE} with rims squeezed narrower than regulation. Players paid $6 a try. {DL} says the rims were bent in transport.",
        state: [E(.forensic, 3, "Rim Measurements", "Rims narrower than posted size."), E(.video, 3, "Player Videos", "Clean shots bounce out repeatedly."), E(.document, 2, "Till Count", "$8,000 taken over a weekend.")],
        defense: [E(.statement, 1, "Transport Damage", "{DL} says rims bent in a move.")],
        role: "Fair safety inspector",
        exam: [.direct("What did you inspect at {D}'s hoop shot booth?", "\"The rims on the game. They were squeezed narrower than regulation size, and I measured each one.\""), .direct("What did the rim measurements show?", "\"Rims narrower than the posted size on the sign. Balls that should go in cannot, because the opening is too small.\""), .direct("What do the player videos show?", "\"Clean shots bouncing out repeatedly. A shot that would drop on a regulation rim rolls around and kicks out.\""), .direct("How much did the booth take in?", "\"$8,000 over a weekend at $6 a try.\""), .direct("Where did the defendant operate this game?", "\"At a county fair, where I inspect rides and midway games for safety and fairness.\""), .direct("What did you do when you found the rims?", "\"I shut the game down and wrote up the narrow rims as a violation.\""), .cross("Could rims bend in transport?", "\"They can bend, yes. A repair receipt says some were bent in a move.\""), .cross("Did anyone win at the game?", "\"A few prizes were won. I do not have a count.\""), .cross("Did the defendant refuse to cooperate?", "\"No. {D} let me measure and did not interfere.\""), .cross("Are the rims on every booth exact?", "\"Not always. Small variations happen, but these were clearly too narrow.\""), .cross("Did you see the defendant adjust a rim?", "\"No. I only saw the finished result.\"")],
        defenseRole: "Booth helper",
        defenseExam: [.direct("What was your job at {D}'s booth?", "\"I helped pitch the balls back to players, handed out the prizes, and collected the $6 from each customer all weekend long.\""), .direct("Did you adjust the rims?", "\"No. I never touched the rims or any of the equipment, because setting up the game was {D}'s job and not mine.\""), .direct("Who handled the rims?", "\"{DF} did. Every morning before we opened, {DF} set up the rims and checked them over before the first customer came.\""), .direct("Did you see the defendant use any special tool?", "\"Once I saw {DF} bent over one of the rims with some kind of tool in hand, working on it for a minute.\""), .direct("How did players do on the game?", "\"Most of them missed. A few made a shot or two, but the big prizes mostly stayed on the shelf all weekend.\""), .direct("Did customers complain?", "\"A few said it felt tight. {DF} told them the game was designed to be hard, and most of them laughed and tried again.\""), .cross("Did you check the rim width yourself?", "\"No. I never measured anything. I only watched the game and took money, so I cannot tell you how wide they were.\""), .cross("What was the tool you saw?", "\"I could not tell you. It looked like a wrench or a clamp, but I was across the booth and not paying close attention.\""), .cross("Did you speak to the defendant about the rims?", "\"No, I did not. I did not think it was my place to question how the owner set up the game.\""), .cross("Did you hear the defendant talk about rim size?", "\"Once, in passing, about dents from transport. I did not follow the conversation closely and I cannot repeat the details.\""), .cross("Did you share in the take?", "\"I was paid a flat wage for the weekend. I did not share in the winnings, and I never saw the final count.\"")],
        theory: ("{D} made a game players could not win.", "Damaged rims."),
        allocution: "\"I knew they were tight.\"",
        truths: ("{DL} bought a rim squeezing tool days before.", "{DL} has a repair receipt for transport dents."),
        defendant: [.direct("Did you narrow the rims on purpose?", "\"No. The rims were bent in transport. I adjusted what I could, but I did not squeeze them to cheat.\""), .direct("What do you have to show about the transport damage?", "\"A repair receipt for dents from moving the game between fairs.\""), .direct("Why did you buy a rim squeezing tool days before?", "\"To fix bent rims, in case they were dented in a move. It is a normal repair tool.\""), .direct("Has anyone ever won on your game?", "\"Yes. A few players have. I do not control the shots.\""), .direct("How did you feel when the inspector found the rims?", "\"I was surprised. I thought they were close to regulation, and I asked what else I could do.\""), .direct("What would you do differently?", "\"Measure every rim before opening. I should have done that.\""), .cross("The rims are narrower than the posted size, aren't they?", "\"They are. I did not measure them closely.\""), .cross("Clean shots bounced out over and over on the videos, didn't they?", "\"It looks that way. The rims bounce hard.\""), .cross("$8,000 in a weekend at a game almost no one wins. Isn't that the point?", "\"It is a hard game. I did not rig it.\""), .cross("You bought the squeezing tool days before the fair, didn't you?", "\"I did, for repairs. I understand how it looks.\""), .cross("Your helper says you adjusted the rims every morning, doesn't your helper?", "\"I checked them every morning. I did not narrow them.\"")],
        openings: ("{D}, a game booth operator, ran a hoop shot game at $6 a try with rims squeezed narrower than regulation. Videos show clean shots bouncing out again and again, and the booth took in $8,000 over a weekend.", "The rims were bent in transport, and {D} has a repair receipt to show it. A hard game is not a rigged game, and a repair tool is not a cheater's tool."),
        closings: ("Narrow rims, shots that bounce out on video, a squeezing tool bought days before, and $8,000 in a weekend. This game was built to take money.", "Dents from transport, a repair receipt, and a game that is hard because hoops are hard. The State has measurements but no proof of intent."),
        timeline: [(-6, "{DL} buys the tool."), (0, "The fair opens."), (2, "Complaints."), (3, "Inspection.")],
        identified: "A fair inspection.",
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

