        defense: [E(.statement, 1, "Candy Duty", "{DL} says a neighbor sent {D.him} with candy.")],
        role: "Homeowner",
        exam: [.direct("What happened at your neighborhood open house?", "\"Someone dressed as an elf wandered upstairs alone during the party and left with a watch case from my room.\""), .direct("What does your hallway camera show?", "\"An elf going upstairs alone and carrying a canvas bag. The elf comes back down a few minutes later.\""), .direct("What was found on the watch case?", "\"Prints on the clasp, which matched {D}. The case was empty when I found it.\""), .direct("Where did a matching watch show up?", "\"A marketplace post listed a matching watch for sale that same week.\""), .direct("Did you invite an elf to the party?", "\"No. I did not hire or ask for anyone dressed as an elf.\""), .direct("Was candy being handed out that night?", "\"No candy bowl was set out. If someone was handing out candy, it was not part of my party.\""), .cross("Neighbors wandered through the house, didn't they?", "\"Yes. It was an open house, and people moved freely.\""), .cross("Did you see {D} take the watch?", "\"No. I only saw the camera afterward.\""), .cross("Could someone have asked the defendant to hand out candy?", "\"I do not know. No one at the party told me.\""), .cross("Could prints be there from a prior visit?", "\"{D.He} has never been upstairs in my home. I do not think so.\""), .cross("Did the defendant try to hide the elf costume?", "\"No. It was a bright costume, and {D.he} wore it into the house.\"")],
