        exam: [.direct("Where do you work?", "\"I am a cashier at a grocery store. I handle the drawer and the register line.\""), .direct("What happened at your register on {DATE}?", "\"{D} slid me a note demanding the drawer. It was written on the back of a store receipt.\""), .direct("What did the receipt show?", "\"It carried a loyalty account in {D.his} name. The note was on the back.\""), .direct("What did you do?", "\"I opened the drawer and handed over cash, because the note scared me. I pressed the alarm afterward.\""), .direct("How much was taken?", "\"$1,400. The drawer count confirmed it afterward.\""), .direct("How did {DL} act?", "\"Quiet and steady. {D.He} did not say much. The camera shows the slide of the note and the cash.\""), .direct("How did you feel while the note was on your counter?", "\"I was frightened. {D.He} was calm and quiet, which made it harder to read. I did not know whether someone had a weapon, so I opened the drawer.\""), .cross("Did you see a weapon?", "\"No. I did not. The note was the threat.\""), .cross("Did you see anyone outside the store?", "\"I did not look. I was focused on the register.\""), .cross("Did {DL} seem nervous?", "\"A little. {D.He} avoided my eyes. I cannot say why.\""), .cross("Did {DL} use a loyalty account on purpose?", "\"I cannot say. It was on the receipt used for the note.\""), .cross("Did {DL} leave quickly?", "\"Yes. Right after taking the cash.\"")],
        defenseRole: "Store manager",
        defenseExam: [.direct("What is your role at the store?", "\"I am the store manager. I review the cameras and handle incidents.\""), .direct("Did you review the register video?", "\"Yes. I watched it several times.\""), .direct("What did {DL} look like on camera?", "\"Calm and quiet. {D} did not rush. {D.He} slid the note and took the cash.\""), .direct("Was a car outside?", "\"One idled at the edge of the lot during the incident. I noticed it on the exterior camera.\""), .direct("Did you recognize the car?", "\"No. I did not. It was not a regular.\""), .direct("Was {DL} a customer before?", "\"Yes. {D.He} has a loyalty account and came in occasionally.\""), .direct("What did the register video show about {D}'s manner at the counter?", "\"{D.He} walked in alone, stood quietly, and slid the note. {D.He} did not rush or look around, which struck me as odd for a robbery.\""), .direct("Did you see a car near the lot on the video?", "\"Yes. A car idled by the edge of the lot for the whole time. I could not see the driver, but it did not move until {DF} left.\""), .direct("How much money was missing from the drawer?", "\"The drawer count was $1,400 short. We recovered none of it that night, and I reported the amount to the sheriff's office.\""), .cross("Does the exterior camera show anyone talking to {DL}?", "\"No. It shows a car. It does not show who was inside.\""), .cross("Did anyone come into the store with {DL}?", "\"No. {D.He} was alone.\""), .cross("Did {DL} speak to anyone before the register?", "\"No. I did not see that.\""), .cross("Did the car leave right after?", "\"I believe so. I cannot say whether {D.he} got in.\""), .cross("Did {DL} ever threaten anyone here before?", "\"No. Never.\"")],
        theory: ("{D} robbed a cashier.", "A forced note."),
        allocution: "\"I needed the money.\"",
        truths: ("{DL} walked in alone and calm.", "A car idled by the lot edge during the robbery."),
        defendant: [.direct("Why did you give the cashier a note?", "\"Someone outside forced me. A person waited in a car and told me what to write. I was afraid.\""), .direct("Why was it on a receipt with your name?", "\"That is what I had in my pocket. The person told me to write quickly. I did not think.\""), .direct("What did the person say?", "\"That something would happen to me if I did not do it. I did not look closely. I did what I was told.\""), .direct("Did you want to rob the store?", "\"No. I never have. I felt trapped and went along.\""), .direct("Why did you not call for help?", "\"I was scared. The person was watching. I did not know who to trust.\""), .direct("What did you do with the money?", "\"I gave it to the person outside. I kept none of it. I felt sick.\""), .direct("What did you do right after the stranger told you to write the note?", "\"I walked into the store alone and slid the note to the cashier. I was terrified, and I did not think to ask anyone for help.\""), .cross("You wrote the note yourself, didn't you?", "\"Yes. I wrote it. I was told to.\""), .cross("You used a receipt with your own loyalty account, didn't you?", "\"Yes. It identified me. A robber would not do that.\""), .cross("The camera shows you walking in alone, doesn't it?", "\"Yes. I walked in alone. The person stayed outside.\""), .cross("No one else appears on the register camera, do they?", "\"No. They were outside. I cannot prove it.\""), .cross("You took $1,400, didn't you?", "\"Yes. I took it and handed it over.\"")],
        openings: ("{D} slid a cashier a note demanding the drawer, written on the back of a store receipt tied to {D}'s own loyalty account, and took $1,400. The register camera shows it. The State will show the note and the video.", "A robber does not sign the note. {D} wrote on a receipt that carried a name, walked in alone, and says someone outside forced it. A manager will tell you a car idled by the lot."),
        closings: ("A note on a receipt with {D}'s name, a calm walk to the register, and $1,400 in a drawer gone. {D} took the money.", "A name on the note and a car idling outside. The State has not proved {D} acted freely rather than under pressure."),
        timeline: [(0, "7 p.m.: the note."), (0, "7:03 p.m.: the cash."), (1, "The receipt is traced."), (3, "Arrest.")],
        identified: "A loyalty account receipt.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let stormLootingCrewV1 = SmallCases.make(
        key: "story.stormLootingCrew",
        category: .property,
        headlines: ["Tree Crew Hired After Ice Storm Hauled Off More Than Branches", "Chain Saws and a Truck Full of Cabinet Hardware"],
        law: "feloniousBE",
        threshold: 7,
        spec: "Broke and entered the building of {V} with intent to commit larceny, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After an ice storm, {D}, a tree worker, went into {V}'s unoccupied lake cabin on {DATE} and carried out tools and a stove. {DL} says {D.he} was told the cabin was abandoned.",
        state: [E(.video, 3, "Neighbor Phone Video", "{D} carries a stove to a truck."), E(.document, 3, "Road Closure Order", "Cabin road closed to all but residents."), E(.forensic, 2, "Truck Search", "Tools engraved with {V}'s mark.", .search)],
        defense: [E(.statement, 1, "Abandoned Cabin", "{DL} says a stranger called it abandoned.")],
        role: "Sheriff's deputy",
        exam: [.direct("Why did you respond to the lake cabin?", "\"After an ice storm, a neighbor filmed {D} carrying a stove to a truck at a cabin that belongs to {V}. We went out to look.\""), .direct("What does the neighbor's phone video show?", "\"It shows {DL} carrying a stove across the yard and loading it into a truck. It is clear.\""), .direct("What was posted about the cabin road?", "\"A road closure order limited the cabin road to residents. {D.He} did not live there.\""), .direct("What did your search of the truck find?", "\"Tools engraved with {V}'s mark, plus the stove in the bed.\""), .direct("How was the cabin kept?", "\"It is a seasonal cabin, closed for the winter, not abandoned. It had a lock and a mailbox.\""), .direct("What did {D} tell you?", "\"That a stranger told {DL} the cabin was abandoned. I did not find the stranger.\""), .cross("The ice storm caused chaos on the lake, didn't it?", "\"It did. Roads were closed and many cabins were damaged.\""), .cross("Could the defendant have thought the cabin was abandoned?", "\"It was dark and iced over. I can see how someone might think so, though it was clearly kept.\""), .cross("Did the defendant resist when you stopped the truck?", "\"No. {D.He} cooperated.\""), .cross("Did the defendant make any effort to hide the truck?", "\"The truck was parked in the open, in view of neighbors.\""), .cross("Did anyone see the defendant break into the cabin?", "\"No. We have a person carrying a stove, not a person forcing a door.\"")],
        defenseRole: "Lake resident",
        defenseExam: [.direct("Is the cabin lived in year round?", "\"No. It is a seasonal cabin that gets closed up for the winter and opened again in the spring by the owner.\""), .direct("Was the cabin abandoned?", "\"No, it was not. It looked shut up for the season, but it was kept, with a lock on the door and a mailbox out front.\""), .direct("Did anyone tell {D} otherwise?", "\"Not me. I never spoke to {D} about the cabin, and I did not know anyone was in there until the deputies came.\""), .direct("What was the lake like after the storm?", "\"Dangerous. Trees were down everywhere, power lines were hanging, and the roads were closed to everyone except residents for days.\""), .direct("Did people come to help clear the lake?", "\"Yes. Many people came with chain saws to help, and {DF} is a tree worker, so seeing {DF}'s truck did not surprise anyone.\""), .direct("Did you see the defendant on the road?", "\"I saw {DF}'s truck on the closed road after the storm, and I figured {DF} was out there doing tree work for somebody.\""), .cross("Did you know the defendant was taking things from the cabin?", "\"No. I had no idea until deputies came to the lake and started asking questions about the cabin and the stove.\""), .cross("Did the defendant ask you whether the cabin was abandoned?", "\"No. {DF} never asked me anything about it, and I would have told {DF} it was a seasonal cabin if asked.\""), .cross("Was there a lock on the cabin door?", "\"Yes. The door was locked before the storm. I do not know how it ended up open, and I did not check it afterward.\""), .cross("Did you see the defendant return to the cabin?", "\"I did not. I only saw the truck on the road once, and I cannot tell you how many times it came back.\""), .cross("Would a worker clear a stove from a cabin?", "\"No. Hauling a stove out of a cabin is not tree work, and nobody on the lake asked {D.him} to do it.\"")],
        theory: ("{D} stripped a closed-off cabin.", "A mistaken belief."),
        allocution: "\"I should have called someone.\"",
        truths: ("{DL} came back twice at night with a trailer.", "A stranger did tell {DL} the cabin was empty."),
        defendant: [.direct("Why did you go to the cabin?", "\"A stranger told me the cabin was abandoned and that the owner wanted the contents cleared. I believed it.\""), .direct("Who was the stranger?", "\"Someone at the lake I never met again. I did not get a name.\""), .direct("Did you take the tools and the stove?", "\"I took them, thinking I was salvaging abandoned things. I intended to keep the stove and use the tools.\""), .direct("Did you break into the cabin?", "\"The door was already open from the storm. I did not force anything.\""), .direct("Why did you come back?", "\"I came back to finish loading. It was foolish, and I should have stopped.\""), .direct("What do you want {V} to know?", "\"I apologize. I should have checked before I took anything.\""), .cross("The cabin road was closed to everyone but residents, wasn't it?", "\"Yes. I drove in anyway, since I work with trees and I knew many were cleared.\""), .cross("You came back twice at night with a trailer, didn't you?", "\"Yes. I did. It looks bad.\""), .cross("Tools engraved with {V}'s mark were in your truck, weren't they?", "\"Yes. I did not look at the engraving.\""), .cross("A stranger told you the cabin was empty. Can you produce that stranger?", "\"No. I cannot. I wish I could.\""), .cross("You are a tree worker. Why were you hauling a stove?", "\"I took it because it looked abandoned. That was foolish.\"")],
        openings: ("After an ice storm, {D}, a tree worker, drove onto a closed cabin road and carried tools and a stove out of {V}'s seasonal lake cabin. A neighbor filmed it, and tools engraved with {V}'s mark were in {D}'s truck.", "A stranger told {D} the cabin was abandoned, and the storm had left everything torn up. {D} acted on a bad tip. A mistaken belief is not a burglar's plan."),
        closings: ("A closed road, a locked seasonal cabin, a stove on camera, and engraved tools in {D}'s truck. {D} went back twice with a trailer.", "A storm, a stranger's word, and a tree worker who took what looked abandoned. {D} owns the mistake, but the State has not shown a plan."),
        timeline: [(-2, "The ice storm."), (0, "1 a.m.: first trip."), (1, "The owner returns."), (6, "Truck search.")],
        identified: "A neighbor's phone video.",
        mood: .wantsConviction,
        doctrines: ["mistakeOfFact"])

    static let vacationRentalNoHouseV1 = SmallCases.make(
        key: "story.vacationRentalNoHouse",
        category: .whiteCollar,
        headlines: ["Mountain Cabin Booked to Dozens of Couples Belonged to Someone Else", "Photos Copied From a Resort Brochure"],
        law: "falsePretenses",
        threshold: 7,
        spec: "Obtained money from others by false pretenses, on or about {DATE}.",
        ages: 22...65,
        victim: false,
        summary: "{D} listed a mountain cabin on a booking site and collected $29,000 in deposits from 30 couples by {DATE}. The cabin is owned by a stranger who never agreed. {DL} says {D.he} thought a partner had a deal with the owner.",
        state: [E(.digital, 3, "Listing", "Photos copied from a resort brochure."), E(.document, 3, "Property Records", "The owner never signed an agreement."), E(.digital, 2, "Payment Records", "$29,000 sent to {D}.")],
        defense: [E(.statement, 1, "Partner Deal", "{DL} says a partner arranged it.")],
        role: "Couple who booked",
        exam: [.direct("How did you find the mountain cabin?", "\"On a booking site, with photos that made it look perfect. We booked for a weekend and paid a deposit to {D}.\""), .direct("What did you learn about the listing?", "\"The photos were copied from a resort brochure. The cabin in the listing does not look like the photos.\""), .direct("What did property records show?", "\"The cabin is owned by a stranger who never agreed to any rental. The owner never signed an agreement with {DL}.\""), .direct("How much did you pay?", "\"Our deposit was part of $29,000 that {D.he} collected from 30 couples. We were one of them.\""), .direct("What happened when you arrived?", "\"The owner met us at the door and told us there was no booking. We stood there with luggage in the rain.\""), .direct("What did you do afterward?", "\"We contacted the booking site and deputies. We lost the deposit and our weekend.\""), .cross("{D} says a partner had a deal with the owner, doesn't {D.he}?", "\"A former partner says the partner did promise a deal. I will agree that is what is claimed.\""), .cross("Did you speak with the partner?", "\"No. I only know what I was told.\""), .cross("Did the defendant refund anyone?", "\"I do not know of anyone who was.\""), .cross("Did the defendant answer your messages before the trip?", "\"Yes. {D.He} was friendly and quick to reply.\""), .cross("Could the defendant have believed the deal was real?", "\"Possibly at first. But {DL} kept taking bookings after the owner said no.\"")],
        defenseRole: "Former partner",
        defenseExam: [.direct("How did you know {D}?", "\"We were partners on a few small ventures over the years, and we talked about listing the mountain cabin together.\""), .direct("Did you speak to the owner of the cabin?", "\"Never. I did not contact the owner at all, and I did not have a signed agreement or even a handshake deal.\""), .direct("Did you tell the defendant you had?", "\"I may have implied it. I said something like 'it is all set,' and I let {D} believe the owner had agreed.\""), .direct("Why did you say that?", "\"I thought the owner would agree once I asked. I wanted the listing to go up quickly, so I skipped a step.\""), .direct("Did you promise the defendant a deal with the owner?", "\"I did promise one, and I truly thought I could get it. I was too sure of myself, and it was not real.\""), .direct("When did you learn the owner said no?", "\"Weeks after bookings had started. I did not tell {D.he} right away because I was embarrassed and hoped to fix it.\""), .cross("Did you tell the defendant when the owner refused?", "\"Not immediately. I was embarrassed and kept quiet for a while, and bookings kept coming in during that time.\""), .cross("You never confirmed the deal with the owner, did you?", "\"No, I never did. I took my own optimism for a deal, and I handed {D.him} that mistake as if it were fact.\""), .cross("Did the defendant ask whether you had a signed agreement?", "\"I do not recall that. {D.He} trusted me, and I did nothing to earn it by showing any paper.\""), .cross("Did you share in the deposits?", "\"No. I received nothing from the couples' money, and I do not know where all of it went once {D.he} collected it.\""), .cross("Were you the one who found the photos?", "\"No. {DF} found the photos. I only told {DF} the cabin was ready, and I never looked at the listing.\"")],
        theory: ("{D} sold stays at a cabin {D.he} had no right to rent.", "A partner's promise."),
        allocution: "\"I trusted the wrong person.\"",
        truths: ("{DL} kept taking bookings after the owner said no.", "The partner did promise a deal."),
        defendant: [.direct("Why did you list the mountain cabin?", "\"A partner told me the owner had agreed to a rental deal. I believed that completely and listed the cabin on the site.\""), .direct("Where did the photos come from?", "\"From a resort brochure that my partner gave me. I did not stop to think about where the pictures originally came from.\""), .direct("Did you speak to the owner?", "\"No. I relied on my partner for everything about the deal, which I now see was a serious mistake on my part.\""), .direct("What did you do when the owner said no?", "\"I did not stop taking bookings right away. I hoped my partner could still make the deal work, and that was wrong.\""), .direct("Did you refund any couples?", "\"A few of them, yes. I did not have enough money left to refund everyone, and that weighs on me every day.\""), .direct("What would you say to those couples?", "\"I am so sorry. I trusted the wrong person, and I should have checked with the owner myself before taking a dollar.\""), .cross("You collected $29,000 from thirty couples for a cabin you had no right to rent, didn't you?", "\"Yes, I did. I honestly thought it would work out, but I took the money before I had any right to.\""), .cross("You kept taking bookings after the owner said no, didn't you?", "\"Yes. That was the worst part of it. I hoped it would be fixed, and I should have shut the listing down.\""), .cross("You copied photos from a resort brochure, didn't you?", "\"They were handed to me, and I used them on the listing. I did not ask whether I was allowed to.\""), .cross("You never saw an agreement, did you?", "\"No, I never saw one. I took my partner's word for it, and I never asked to see anything in writing.\""), .cross("You refunded only a few couples, didn't you?", "\"Yes, only a few. I ran out of money, and I did not know how to make the rest right.\"")],
        openings: ("{D} listed a mountain cabin on a booking site with photos copied from a resort brochure and collected $29,000 in deposits from 30 couples. The cabin belongs to a stranger who never agreed to rent it.", "{D} thought a partner had a deal with the owner and listed in good faith. Trusting the wrong partner is a poor choice. It is not a scheme."),
        closings: ("Thirty couples, $29,000, borrowed photos, and an owner who never agreed to any rental. {D} kept taking bookings even after the owner said no, and kept the money.", "A partner's promise, a listing posted in trust, and a few refunds paid back. The State must prove {D} knew from the very start that there was no deal."),
        timeline: [(-100, "The partner talks of a deal."), (-40, "The owner refuses."), (0, "Couples arrive."), (12, "Charges.")],
        identified: "Payment records.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let fairgroundSwingFallV1 = SmallCases.make(
        key: "story.fairgroundSwingFall",
        category: .violent,
        headlines: ["Coaster Cart Slid Off Track at a Harvest Festival, Injuring Five Riders", "Brake Pad Worn to Metal, Logs Show No Check"],
        law: "aisi",
        threshold: 7,
        spec: "Inflicted serious injury on {V} through culpable negligence, on or about {DATE}.",
        ages: 21...65,
        victim: true,
        summary: "A small coaster at a harvest festival on {DATE} ran into its stop and threw five riders when a brake pad failed. {D}, the operator, signed the daily safety card. {DL} says the pad was replaced under a service contract.",
        state: [E(.forensic, 3, "Brake Pad", "Worn through to metal."), E(.document, 3, "Safety Card", "Signed by {D} that morning."), E(.document, 2, "Service Log", "No pad check in 14 months.")],
        defense: [E(.document, 1, "Service Contract", "A contract that covered brake work.")],
        role: "Ride safety inspector",
        exam: [.direct("What is your role?", "\"I am a ride safety inspector. I examine rides after incidents and review maintenance records.\""), .direct("What happened at the harvest festival on {DATE}?", "\"A small coaster ran into its stop and threw five riders when a brake pad failed.\""), .direct("What did you find in the brake pad?", "\"It was worn through to metal. There was nothing left to create friction.\""), .direct("What does the safety card show?", "\"{D}, the operator, signed the daily safety card that morning. It says the ride was inspected.\""), .direct("What does the service log show?", "\"No pad check in fourteen months. There is a gap that long between entries on the brakes.\""), .direct("How serious were the injuries?", "\"Five riders were thrown and hurt. I will let the medical records speak to the degree.\""), .direct("What did the service log show about the brake pad?", "\"It showed no brake pad check for fourteen months. A pad worn through to metal is something a regular inspection should have caught well before the accident.\""), .cross("Is the operator supposed to replace brake pads?", "\"No. A mechanic does that. The operator performs daily checks.\""), .cross("Did {DL} sign the card honestly?", "\"I cannot say what {D.he} checked. The card says it was inspected.\""), .cross("Was there a service contract?", "\"Yes. A contract that covered brake work existed. I do not know if it was performed.\""), .cross("Could a pad wear out between checks?", "\"Yes. That is why checks are required. Fourteen months is too long.\""), .cross("Did {DL} try to hide the log gap?", "\"No. The log was available. {D.He} showed it to me.\"")],
        defenseRole: "Ride mechanic",
        defenseExam: [.direct("What is your role?", "\"I am a ride mechanic. I service rides under contracts.\""), .direct("Did you service this coaster?", "\"Yes, under a service contract that covered brake work.\""), .direct("What does the contract cover?", "\"Periodic inspections and parts replacement. It is a standard agreement.\""), .direct("Did {DL} pay for the contract?", "\"Yes. {D} paid the fees on time.\""), .direct("Did you replace the brake pad?", "\"I do not have a record of a pad replacement in that period. I would need to check.\""), .direct("Does an operator replace pads?", "\"No. A mechanic does. The operator does daily checks.\""), .direct("Describe what you did for this ride under the contract.", "\"I serviced the coaster on a regular schedule. My work covered periodic inspections and parts replacement, including brake pads when they were due.\""), .direct("How often should a brake pad be checked on a ride like this?", "\"At least every few months, depending on use. A coaster that runs all day at a festival needs checks more often, and the pad can wear fast.\""), .direct("What would a daily operator check normally include?", "\"A walk-around, a test run, and a brake test. The operator signs a card after the test, and that check is the operator's job, not mine.\""), .cross("Did you inspect the pad in the last fourteen months?", "\"I do not have a record. I cannot say.\""), .cross("Did {DL} ask you to check the brakes?", "\"Not that I recall.\""), .cross("Did you tell {DL} brakes were fine?", "\"I do not think I did. I did not speak to {D.him} about the pad.\""), .cross("Did the contract require quarterly checks?", "\"It required periodic checks. I would have to review the terms.\""), .cross("Are you responsible for the gap in the log?", "\"Partly. I should have caught it.\"")],
        theory: ("{D} signed off on a ride with failing brakes.", "A service contract."),
        allocution: "\"I relied on the contract.\"",
        truths: ("{DL} skipped the daily brake test.", "{DL} did pay for a service contract."),
        defendant: [.direct("What is your job at the festival?", "\"I operate the coaster. I start it, watch the riders, and do the daily walk-around.\""), .direct("What did you do the morning of the accident?", "\"I signed the daily safety card after a walk-around. The ride looked normal.\""), .direct("Did you check the brakes?", "\"I looked at what an operator can see. I thought the service contract covered pad work.\""), .direct("What did you believe about the pad?", "\"That it was replaced under the service contract. I trusted the mechanic and the paperwork.\""), .direct("How has this affected you?", "\"Heartbroken. I would give anything to undo it. I check this ride with care.\""), .direct("Do you accept responsibility?", "\"I accept that I signed a card for a ride that was not safe. I never knew the pad was gone.\""), .direct("Did you do the daily brake test that morning?", "\"I did a walk-around and signed the card, but I skipped the full brake test. I assumed the service contract covered it, and I know that was wrong.\""), .cross("The pad was worn to metal, wasn't it?", "\"Yes. That is what the inspector found. I did not see it.\""), .cross("You signed the card that morning, didn't you?", "\"Yes. I did. I thought it was safe.\""), .cross("The log shows no pad check for fourteen months, doesn't it?", "\"It does. I assumed the contract covered it.\""), .cross("Did you look at the log before signing?", "\"No. That is on me. I trusted what I was told.\""), .cross("You are responsible for rider safety, aren't you?", "\"Yes. I know it. That is why this hurts.\"")],
        openings: ("A small coaster at a harvest festival ran into its stop and threw five riders when a brake pad failed. The pad was worn to metal, {D} signed the daily safety card, and the log shows no pad check in 14 months. The State will show the pad and the log.", "A service contract covered brake work, and {D} paid for it. A ride mechanic will tell you who was supposed to replace the pad, and it was not the operator."),
        closings: ("A pad worn to metal, a safety card signed that morning, and a log with a fourteen-month gap. Five riders were thrown because no one looked.", "{D} operated a ride that a mechanic was paid to maintain. The State has not proved {D} knew the pad was gone."),
        timeline: [(-420, "The last pad check."), (-1, "{DL} signs the safety card."), (0, "The cart leaves the track."), (18, "Report.")],
        identified: "The failed brake pad.",
        mood: .divided,
        doctrines: ["burdenOfProof"])

    static let campgroundBluegrassBrawlV1 = SmallCases.make(
        key: "story.campgroundBluegrassBrawl",
        category: .violent,
        headlines: ["Fiddle Contest Campsite Feud Ends With a Cooler Swung at a Man's Face", "Orbital Bone Broken at Mountain Music Gathering"],
