        threshold: 6,
        spec: "Assaulted {V} inflicting serious injury, on or about {DATE}.",
        ages: 21...65,
        victim: true,
        summary: "At a fiddle gathering campground on {DATE}, {D} and {V} argued over a tent line, and {V} left with a broken eye socket. {DL} says {V} threw a lantern first.",
        state: [E(.forensic, 3, "Medical Report", "A fractured orbital bone."), E(.video, 3, "Camper Phone Video", "{D} swings a cooler lid."), E(.statement, 2, "Neighbor Statements", "Two neighbors say {D} swung first.")],
        defense: [E(.video, 1, "Other Clip", "A clip of {V} hurling a lantern.")],
        role: "Neighboring camper",
